            check('relatedAppPreserved', String(f.lookup?.relatedApp?.app ?? '') === String(snapF.lookup?.relatedApp?.app ?? ''), String(snapF.lookup?.relatedApp?.app ?? ''), String(f.lookup?.relatedApp?.app ?? ''));
            const expF = expected.fields?.properties?.[code] || {};
