        const dRefs = decisionRefsOf(o.decisionRefs);
        const quotes = (Array.isArray(o.sourceQuotes) ? o.sourceQuotes : []).filter(q => typeof q === 'string' && inUser(q)).map(q => reqText(q, 300)).slice(0, 5);
