        const genW = cls.intent === INTENT.REVISE_PLAN && cls.reason === 'TURN_THEN_GENERATE';
        // 同じ修正の依頼（［再試行］・二重クリック）は、いまの作業か受け口にあれば積まない（以前は同じ依頼で全体の作り直しがもう 1 回走った）
        const sameAs = (x) => x === t || (!!cls.restText && x === cls.restText);
