            if (!(outA.adoptNoRec && outA.adoptNoRec.length)) toolkit('回答として記録できる内容がありませんでした。作り直しの後に、最終案のカードの回答欄から送ってください。', { kind: 'answers-none', planId: base.planId, version: base.version });
