          if (Array.isArray(prevEntry.requiredEffects)) { const rq = requiredOf(v, c.customizationId); if (rq.unresolved.length || effectsKeyOf(rq.effects) !== effectsKeyOf(prevEntry.requiredEffects)) return no('requirements'); }
